Source code in <code>src/doublegate_sdk/checks.py</code> <pre><code>@dataclass(frozen=True, slots=True)
class ScanResult:
    outcome: str                                    # "clean" | "flagged"
    findings: tuple[Finding, ...] = ()
    masked: str = ""                                # the body a gate prompt may see

    @property
    def flagged(self) -&gt; bool:
        return self.outcome == "flagged"

    def to_payload(self) -&gt; dict[str, Any]:
        return {"outcome": self.outcome, "findings": [f.to_dict() for f in self.findings]}
